// Execute in a disposable Linux API runtime with current compiled PDF modules.
import assert from 'node:assert/strict';

import { mkdtemp, readdir, rm, mkdir } from 'node:fs/promises';
import { join } from 'node:path';

import { LocalPdfOcrEngine } from '../dist/pdf-ocr.js';
import {
  extractPdfAttachment,
  PdfPageLimitError,
  PdfOcrFailedError,
} from '../dist/pdf-attachments.js';

const directory = await mkdtemp('/tmp/modelnaru-n13-ocr-');
function pdf(objects) {
  const parts = [Buffer.from('%PDF-1.4\n')],
    offsets = [0];
  for (const [index, object] of objects.entries()) {
    offsets.push(parts.reduce((n, part) => n + part.length, 0));
    parts.push(
      Buffer.from(`${index + 1} 0 obj\n`),
      Buffer.from(object),
      Buffer.from('\nendobj\n'),
    );
  }
  const xref = parts.reduce((n, part) => n + part.length, 0);
  parts.push(
    Buffer.from(
      `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n` +
        offsets
          .slice(1)
          .map((n) => String(n).padStart(10, '0') + ' 00000 n \n')
          .join('') +
        `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`,
    ),
  );
  return Buffer.concat(parts);
}
const stream = (dictionary, bytes) =>
  Buffer.concat([
    Buffer.from(`<< ${dictionary} /Length ${bytes.length} >>\nstream\n`),
    bytes,
    Buffer.from('\nendstream'),
  ]);
try {
  // Generated Arial raster: no font dependency inside the OCR container.
  const raster = Buffer.from(
    '',
    'base64',
  );
  const draw = Buffer.from('q 600 0 0 400 0 0 cm /Im0 Do Q');
  const scanned = pdf([
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 400] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>',
    stream(
      '/Type /XObject /Subtype /Image /Width 1200 /Height 800 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode',
      raster,
    ),
    stream('', draw),
  ]);
  const temporaryRoot = join(directory, 'workers');
  await mkdir(temporaryRoot);
  const engine = new LocalPdfOcrEngine(temporaryRoot);
  const result = await extractPdfAttachment(scanned, 1, engine);
  assert.equal(result.ocrPageCount, 1);
  assert.equal(result.pageCount, 1);
  assert.match(result.text, /MODEL NARU OCR ACCEPTANCE/);
  assert.deepEqual(await readdir(temporaryRoot), []);
  await assert.rejects(
    extractPdfAttachment(scanned, 0, engine),
    PdfPageLimitError,
  );
  await assert.rejects(
    engine.recognize(Buffer.from('%PDF-invalid'), 1),
    PdfOcrFailedError,
  );
  assert.deepEqual(await readdir(temporaryRoot), []);
  const koreanRaster = Buffer.from(
    '',
    'base64',
  );
  const korean = pdf([
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 600 400] /Resources << /XObject << /Im0 4 0 R >> >> /Contents 5 0 R >>',
    stream(
      '/Type /XObject /Subtype /Image /Width 1200 /Height 800 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode',
      koreanRaster,
    ),
    stream('', draw),
  ]);
  const koreanResult = await extractPdfAttachment(korean, 1, engine);
  assert.equal(koreanResult.ocrPageCount, 1);
  assert.match(koreanResult.text.replace(/\s/gu, ''), /모델나루한국어문서시험/);
  assert.match(koreanResult.text.replace(/\s/gu, ''), /오늘날씨는맑습니다/);
  assert.match(koreanResult.text, /12345/);
  assert.deepEqual(await readdir(temporaryRoot), []);
  console.log(
    JSON.stringify({
      scannedPdfOcr: 'passed',
      pageLimit: 'passed',
      invalidPdf: 'passed',
      temporaryCleanup: 'passed',
      languages:
        'kor+eng; English and Korean synthetic raster assertions passed',
      koreanScannedPdfOcr: 'passed',
    }),
  );
} finally {
  await rm(directory, { recursive: true, force: true });
}
